98d0b311-eb0d-40ca-9bb9-ec2b5b64c567.script:
"/**
 * Created by the Ping Identity Technology Alliance Partner (TAP) team
 *
 * For support, contact Ping Identity Support
 * or email: tap-global@pingidentity.com
 *
 * Version: 1.5
 */

try {
    var accessToken = nodeState.get("pingAccessToken");
    var userId = nodeState.get("pingOneUserId");
    var envId = systemEnv.getProperty("esv.envid");

    if (!accessToken || !userId || !envId) {
        logger.error("Missing required values. accessToken=" + !!accessToken +
                     ", userId=" + !!userId +
                     ", envId=" + !!envId);
        action.goTo("error");
    } else {
        var requestUrl = "https://api.pingone.com/v1/environments/"
            + encodeURIComponent(envId)
            + "/users/"
            + encodeURIComponent(userId)
            + "/mfaEnabled";

        var options = {
            method: "PUT",
            headers: {
                "Content-Type": "application/json",
            },
            token: accessToken,
            body: {
                mfaEnabled: true
            }
        };

        var response = httpClient.send(requestUrl, options).get();

        logger.info("PingOne MFA enable response status: {}", response.status);

        if (response.status >= 200 && response.status < 300) {
            nodeState.putShared("mfaEnabledResult", "success");
            action.goTo("success");
        } else {
            var responseBody = "";
            try {
                responseBody = response.text();
            } catch (ignore) {}

            logger.error("PingOne MFA enable failed. Status: " +
                         response.status + ", Body: " + responseBody);

            nodeState.putShared("mfaEnabledResult", "failed");
            nodeState.putShared("mfaEnabledStatus", String(response.status));
            nodeState.putShared("mfaEnabledBody", responseBody);

            action.goTo("error");
        }
    }
} catch (e) {
    logger.error("Exception enabling MFA: {}", String(e));
    nodeState.putShared("mfaEnabledResult", "exception");
    nodeState.putShared("mfaEnabledException", String(e));
    action.goTo("error");
}"

ebc5c694-7be9-4e53-ab0a-738ad9bbc552.script:
"/**
 * Created by the Ping Identity Technology Alliance Partner (TAP) team
 *
 * For support, contact Ping Identity Support
 * or email: tap-global@pingidentity.com
 *
 * Version: 1.5
 */

var accessToken = nodeState.get("pingAccessToken");
var userId = nodeState.get("pingOneUserId");
var envId = systemEnv.getProperty("esv.envid");
var policyid = systemEnv.getProperty("esv.policyid");
var applicationid = systemEnv.getProperty("esv.applicationid");

var url = `https://api.pingone.com/v1/environments/${envId}/users/${userId}/pairingKeys`;

var requestOptions = {
  method: "POST",
  headers: {
    "Content-Type": "application/json"
  },
  token: accessToken,
  body: {
    applications: [
      {
        id: applicationid
      }
    ],
    policy: {
      id: policyid
    }
  }
};

try {
  var response = httpClient.send(url, requestOptions).get();

  if (response.ok) {
    var responseJson = response.json();

    // Store the returned pairing code in shared state.
    nodeState.putShared("pairingKeyCode", responseJson.code);
      nodeState.putShared("pairingKeyId", responseJson.id);
      nodeState.putShared("pairingKeyUri", responseJson.uri);


    action.goTo("true");
  } else {
    logger.error("Pairing key request failed: " + response.status + " " + response.text());
    nodeState.putShared("pairingKeyError", response.text());
    action.goTo("false");
  }
} catch (e) {
  logger.error("Pairing key request exception: " + e);
  nodeState.putShared("pairingKeyError", String(e));
  action.goTo("false");
}"

